"""Verify thermal record encoding against the native builder and a captured program."""

import json
import unittest
from pathlib import Path

from .protocol import ABI7500ProtocolError
from .thermal_program import ThermalCycle, ThermalProgram, ThermalStep

_DATA = Path(__file__).parent / "test_data"


class ThermalProgramTests(unittest.TestCase):
  """Program fields must retain exact temperature/time precision and cycle structure."""

  def test_native_builder_vectors(self) -> None:
    """Compare generated bytes to independently emulated native AddSegment/AddSetpoint calls."""
    vectors = json.loads((_DATA / "thermal_program_vectors.json").read_text())["vectors"]
    for vector in vectors:
      with self.subTest(name=vector["name"]):
        expected = bytes.fromhex(vector["payload_hex"])
        cycles = tuple(
          ThermalCycle(
            cycle["repetitions"],
            tuple(
              ThermalStep(
                step["temperature"] / 10,
                step["hold"],
                step["ramp"],
                step["hold_increment"],
                step["temperature_increment"] / 10,
              )
              for step in cycle["steps"]
            ),
          )
          for cycle in vector["cycles"]
        )
        program = ThermalProgram(expected[1:48], cycles)
        self.assertEqual(program.encode(), expected)
        self.assertEqual(ThermalProgram.decode(expected), program)

  def test_captured_program_matches_saved_run_settings(self) -> None:
    """The on-wire method represents the independently saved two-cycle experiment."""
    vector = json.loads((_DATA / "usb_run_vectors.json").read_text())["vectors"][0]
    wire = bytes.fromhex(vector["payload_hex"])
    program = ThermalProgram.decode(wire)
    self.assertEqual(
      program.cycles,
      (
        ThermalCycle(1, (ThermalStep(95, 15),)),
        ThermalCycle(2, (ThermalStep(95, 15), ThermalStep(60, 60))),
      ),
    )
    self.assertEqual(program.encode(), wire)

  def test_rejects_incomplete_and_unsupported_records(self) -> None:
    """Never discard an unrecognized pause, emulation flag, or trailing record."""
    vector = json.loads((_DATA / "usb_run_vectors.json").read_text())["vectors"][0]
    wire = bytes.fromhex(vector["payload_hex"])
    for size in range(len(wire)):
      with self.subTest(size=size), self.assertRaises(ABI7500ProtocolError):
        ThermalProgram.decode(wire[:size])
    for offset, value in ((0, 1), (0, 3), (48, 4), (49, 1), (51, 3), (58, 4), (59, 1)):
      changed = bytearray(wire)
      changed[offset] = value
      with self.subTest(offset=offset), self.assertRaises(ABI7500ProtocolError):
        ThermalProgram.decode(bytes(changed))
    with self.assertRaises(ABI7500ProtocolError):
      ThermalProgram.decode(wire + bytes(10))

  def test_rejects_rounding_and_out_of_range_effective_steps(self) -> None:
    """Do not silently round temperatures or allow increments to exceed finite-hold bounds."""
    for temperature in (float("nan"), float("inf"), 60.01, 3.9, 100.0, True):
      with self.subTest(temperature=temperature), self.assertRaises(ValueError):
        ThermalStep(temperature, 10)
    for hold in (-1, 5940, True):
      with self.assertRaises(ValueError):
        ThermalStep(60, hold)
    with self.assertRaises(ValueError):
      ThermalCycle(10, (ThermalStep(95, 10, temperature_increment=1),))
    with self.assertRaises(ValueError):
      ThermalCycle(3, (ThermalStep(60, 1, hold_time_increment=-1),))
